sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var savedTestMode = gs.getProperty('x_fed_day2_ops.test_mode', 'false');
  try {
    gs.setProperty('x_fed_day2_ops.test_mode', 'false');
    var sam = new x_fed_day2_ops.SamCorrelationClient();
    var pulled = sam.fetchIdentityRequest('ATF-SAM-0006');
    if (pulled.ok) {
      stepResult.setFailed('fetchIdentityRequest reported ok in live mode with no tenant wiring — an unverifiable push must never be treated as approved');
      return;
    }
    if (pulled.reason.indexOf('not implemented') === -1) {
      stepResult.setFailed('expected the fail-closed "not implemented" reason, got: ' + pulled.reason);
      return;
    }
    stepResult.setSuccess();
  } finally {
    gs.setProperty('x_fed_day2_ops.test_mode', savedTestMode);
  }
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var savedTestMode = gs.getProperty('x_fed_day2_ops.test_mode', 'false');
  try {
    gs.setProperty('x_fed_day2_ops.test_mode', 'false');
    var sam = new x_fed_day2_ops.SamCorrelationClient();
    var jws = sam.verifyJws('any-caller-supplied-token', 'any-configured-key');
    if (jws.ok) {
      stepResult.setFailed('verifyJws reported ok in live mode with no real signature verification wired');
      return;
    }
    stepResult.setSuccess();
  } finally {
    gs.setProperty('x_fed_day2_ops.test_mode', savedTestMode);
  }
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var endpoint = gs.getProperty('x_fed_day2_ops.iiq_verify_endpoint', '');
  var jwsKey = gs.getProperty('x_fed_day2_ops.sam_jws_public_key', '');
  if (endpoint || jwsKey) {
    stepResult.setFailed('fixture drifted: this ATF instance has a verification method configured, so this refusal path is not being exercised as intended');
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);
